const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};

const payload = source.payload || {};
const message =
  source.message ||
  payload.message ||
  payload.body?.message ||
  {};

const chatId =
  source.chatId ||
  message.chat?.id ||
  payload.chatId ||
  '';

const raw = String(
  source.rawText ||
  source.text ||
  source.fileName ||
  args.fileName ||
  args.targetName ||
  message.text ||
  payload.text ||
  ''
).trim();

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^["'“”‘’]+|["'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

function extractFileName(rawText) {
  const original = String(rawText || '').trim();
  const normalized = normalize(original);

  const prefixes = [
    'download file',
    'download tep',
    'tai file',
    'tai tep',
    'tai xuong file',
    'tai xuong tep',
    'gui toi file',
    'gui toi tep',
    'gui file',
    'send me file',
    'send file',
    'lay file',
    'lay tep'
  ];

  for (const prefix of prefixes) {
    if (normalized.startsWith(prefix + ' ')) {
      return cleanName(original.slice(prefix.length + 1));
    }

    if (normalized === prefix) {
      return '';
    }
  }

  return '';
}

const fileId =
  source.fileId ||
  source.targetId ||
  args.fileId ||
  args.targetId ||
  payload.fileId ||
  payload.targetId ||
  '';

const fileName = cleanName(
  source.fileName ||
  source.targetName ||
  args.fileName ||
  args.targetName ||
  payload.fileName ||
  payload.targetName ||
  extractFileName(raw)
);

const hasTarget = Boolean(fileId || fileName);

return [{
  json: {
    ...source,
    payload,
    message,
    chatId,
    raw,
    rawText: raw,
    text: normalize(raw),

    fileId,
    targetId: fileId,
    fileName,
    targetName: fileName,

    hasTarget,
    response: hasTarget
      ? ''
      : '📥 <b>Tải file từ Drive</b>\n\nVí dụ:\n<code>tải file báo cáo.pdf</code>\n<code>download file test_n8n.md</code>'
  }
}];

const source = $('Prepare Action').item.json || {};

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const rows = $input
  .all()
  .map((item) => item.json || {})
  .filter((item) => item.id || item.name);

if (!rows.length) {
  return [{
    json: {
      ...source,
      found: false,
      fileId: '',
      targetId: '',
      response: 'Không tìm thấy file phù hợp với: <b>' + escapeHtml(source.fileName || source.targetName || '') + '</b>',
      text: 'Không tìm thấy file phù hợp với: ' + String(source.fileName || source.targetName || '').trim()
    }
  }];
}

const file = rows[0];

return [{
  json: {
    ...source,
    ...file,
    found: true,
    fileId: file.id || source.fileId || '',
    targetId: file.id || source.targetId || source.fileId || '',
    fileName: file.name || source.fileName || source.targetName || '',
    targetName: file.name || source.targetName || source.fileName || '',
    webViewLink: file.webViewLink || source.webViewLink || '',
    webContentLink: file.webContentLink || source.webContentLink || '',
    mimeType: file.mimeType || source.mimeType || ''
  }
}];

const prepared = $('Prepare Action').item.json || {};
const meta = $input.item.json || {};

const fileId = meta.id || prepared.fileId || prepared.targetId || '';
const fileName = meta.name || prepared.fileName || prepared.targetName || 'download';
const mimeType = meta.mimeType || prepared.mimeType || '';
const isGoogleWorkspace = String(mimeType).startsWith('application/vnd.google-apps');

const webViewLink =
  meta.webViewLink ||
  prepared.webViewLink ||
  (fileId ? `https://drive.google.com/file/d/${fileId}/view` : '');

const downloadUrl = fileId
  ? `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}?alt=media&supportsAllDrives=true`
  : '';

const caption = [
  '📥 <b>Đã tải file từ Google Drive</b>',
  '',
  `📄 <b>${fileName.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')}</b>`,
  mimeType ? `Loại: <code>${mimeType.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')}</code>` : '',
  fileId ? `ID: <code>${fileId.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')}</code>` : ''
].filter(Boolean).join('\n');

const workspaceResponse = [
  '⚠️ <b>Đây là file Google Workspace</b>',
  '',
  `File: <b>${fileName.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')}</b>`,
  'Google Docs/Sheets/Slides không tải trực tiếp bằng flow Download.',
  'Hãy dùng lệnh <code>xuất file ... sang pdf/docx/xlsx/pptx</code>.',
  webViewLink ? `🔗 <a href="${webViewLink.replace(/&/g, '&amp;').replace(/"/g, '&quot;')}">Mở file gốc</a>` : ''
].filter(Boolean).join('\n');

const workspaceText = [
  'Đây là file Google Workspace.',
  `File: ${fileName}`,
  'Google Docs/Sheets/Slides không tải trực tiếp bằng flow Download.',
  'Hãy dùng lệnh xuất file ... sang pdf/docx/xlsx/pptx.',
  webViewLink ? `Mở file gốc: ${webViewLink}` : ''
].filter(Boolean).join('\n');

return [{
  json: {
    ...prepared,
    ...meta,
    fileId,
    targetId: fileId,
    fileName,
    mimeType,
    webViewLink,
    downloadUrl,
    isGoogleWorkspace,
    caption,
    response: isGoogleWorkspace ? workspaceResponse : '',
    text: isGoogleWorkspace ? workspaceText : ''
  }
}];

const meta = $('Prepare Download').item.json || {};
const item = $input.item || {};
const json = item.json || {};
const binary = item.binary || {};

const fileName = meta.fileName || meta.name || 'download';
const mimeType = meta.mimeType || 'application/octet-stream';

if (!binary.data) {
  return [{
    json: {
      ...meta,
      response: 'Không tải được binary của file. Hãy mở link file gốc để kiểm tra quyền truy cập.'
    }
  }];
}

binary.data.fileName = binary.data.fileName || fileName;
binary.data.mimeType = binary.data.mimeType || mimeType;

return [{
  json: {
    ...meta,
    ...json,
    chatId: meta.chatId,
    caption: meta.caption || `📥 ${fileName}`
  },
  binary
}];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
